use js_runtime::{Runtime,Value,JsResult,JsError,EnvId};
fn call(rt:&mut Runtime,receiver:Value,name:&str,args:&[Value])->JsResult<Value>{let key=rt.string(name);let method=rt.get(receiver,key)?;rt.call(method,receiver,args)}
fn number(rt:&mut Runtime,object:Value,name:&str)->f64{let key=rt.string(name);match rt.get(object,key).unwrap(){Value::Number(n)=>n,_=>panic!("not Number")}}
fn text(rt:&mut Runtime,object:Value,name:&str)->Vec<u16>{let key=rt.string(name);match rt.get(object,key).unwrap(){Value::String(id)=>rt.string_units(id).to_vec(),_=>panic!("not String")}}
fn invalid_exec(_: &mut Runtime,_:Value,_:&[Value],_:EnvId)->JsResult<Value>{Ok(Value::Bool(true))}
#[test]
fn captures_indices_and_global_last_index_are_live(){let mut rt=Runtime::new();let regex=rt.regexp("(?<letter>a)(b)?","dg").unwrap();let input=rt.string("aab");let first=call(&mut rt,regex,"exec",&[input]).unwrap();assert_eq!(text(&mut rt,first,"0"),[97]);assert_eq!(number(&mut rt,first,"index"),0.0);assert_eq!(number(&mut rt,regex,"lastIndex"),1.0);let second=call(&mut rt,regex,"exec",&[input]).unwrap();assert_eq!(text(&mut rt,second,"0"),[97,98]);assert_eq!(number(&mut rt,regex,"lastIndex"),3.0);assert_eq!(call(&mut rt,regex,"exec",&[input]).unwrap(),Value::Null);assert_eq!(number(&mut rt,regex,"lastIndex"),0.0);}
#[test]
fn unicode_and_nonunicode_iteration_preserve_utf16_units(){let mut rt=Runtime::new();let input=rt.string_utf16(&[0xd83d,0xde00,97]);let regex=rt.regexp(".","g").unwrap();let matches=call(&mut rt,input,"match",&[regex]).unwrap();assert_eq!(number(&mut rt,matches,"length"),3.0);assert_eq!(text(&mut rt,matches,"0"),[0xd83d]);let regex=rt.regexp(".","gu").unwrap();let matches=call(&mut rt,input,"match",&[regex]).unwrap();assert_eq!(number(&mut rt,matches,"length"),2.0);assert_eq!(text(&mut rt,matches,"0"),[0xd83d,0xde00]);}
#[test]
fn sticky_failure_resets_lastindex_but_nonglobal_preserves_it(){let mut rt=Runtime::new();let input=rt.string("ba");let sticky=rt.regexp("a","y").unwrap();assert_eq!(call(&mut rt,sticky,"exec",&[input]).unwrap(),Value::Null);let key=rt.string("lastIndex");rt.set(sticky,key,Value::Number(1.0),true).unwrap();assert_ne!(call(&mut rt,sticky,"exec",&[input]).unwrap(),Value::Null);let plain=rt.regexp("a","").unwrap();rt.set(plain,key,Value::Number(17.0),true).unwrap();let matched=call(&mut rt,plain,"exec",&[input]).unwrap();assert_eq!(number(&mut rt,matched,"index"),1.0);assert_eq!(number(&mut rt,plain,"lastIndex"),17.0);}
#[test]
fn custom_exec_result_validation_and_readonly_lastindex_throw(){let mut rt=Runtime::new();let regex=rt.regexp("a","g").unwrap();let input=rt.string("a");let key=rt.string("lastIndex");rt.define_data(regex,key,Value::Number(0.0),false,false,false).unwrap();assert!(matches!(call(&mut rt,regex,"exec",&[input]),Err(JsError::TypeError(_))));let regex=rt.regexp("a","").unwrap();let exec=rt.native_function("exec",1,invalid_exec).unwrap();let key=rt.string("exec");rt.set(regex,key,exec,true).unwrap();assert!(matches!(call(&mut rt,regex,"test",&[input]),Err(JsError::TypeError(_))));}
#[test]
fn empty_global_matches_advance_without_changing_exec_zero_width_rule(){let mut rt=Runtime::new();let regex=rt.regexp("(?:)","g").unwrap();let input=rt.string("a");call(&mut rt,regex,"exec",&[input]).unwrap();assert_eq!(number(&mut rt,regex,"lastIndex"),0.0);let matches=call(&mut rt,input,"match",&[regex]).unwrap();assert_eq!(number(&mut rt,matches,"length"),2.0);assert_eq!(number(&mut rt,regex,"lastIndex"),0.0);assert!(matches!(rt.regexp("x","gg"),Err(JsError::SyntaxError(_))));}
